problem:
Problem description
- There is a single-period production planning problem with a finite set of products $$\mathcal{P}$$ and a finite set of limited resources $$\mathcal{R}$$.
- Each product $$p \in \mathcal{P}$$ consumes a fixed amount of each resource when one unit is produced, and these consumption coefficients are given by $$a_{p,r}$$ for every resource $$r \in \mathcal{R}$$.
- Each resource $$r \in \mathcal{R}$$ has an available capacity $$b_r$$ for the planning horizon $$\mathcal{T}$$.
- Each product has an ordered set of sales-volume tiers $$\mathcal{K}_p$$. For each tier $$k \in \mathcal{K}_p$$, there is a lower volume bound $$\ell_{p,k}$$, an upper volume bound $$u_{p,k}$$, and a unit-profit value $$\pi_{p,k}$$.
- The unit profit for a product depends on which sales-volume tier its total planned quantity falls into. Higher-volume tiers correspond to lower unit profits, reflecting bulk-discount behavior.
- The objective is to choose the production and sales quantities for all products so that total profit is maximized while all resource and tier rules are respected.
- The plan must use nonnegative quantities for all products.
- The total resource usage implied by the chosen production plan must not exceed the available capacity of any resource.
- For each product, exactly one sales-volume tier must be active, and the chosen quantity for that product must be consistent with the bounds of that tier.
- The tier structure for each product is ordered and non-overlapping, with the final tier allowed to extend without an upper limit when applicable.
- A solution is represented by:
  - $$x_p$$: the planned production and sales quantity of product $$p$$.
  - $$k_p$$: the selected sales-volume tier for product $$p$$.
  - $$y_{p,k}$$: an optional tier-indicator representation showing whether tier $$k$$ is active for product $$p$$.
  - $$\Pi$$: the total profit of the selected production plan.

Input Format
{
  "products": {
    "symbol": "$$\\mathcal{P}$$",
    "type": "array[string]",
    "description": "Product identifiers indexed by $$p \\in \\mathcal{P}$$."
  },
  "resources": {
    "symbol": "$$\\mathcal{R}$$",
    "type": "array[string]",
    "description": "Resource identifiers indexed by $$r \\in \\mathcal{R}$$."
  },
  "time_horizon": {
    "symbol": "$$\\mathcal{T}$$",
    "type": "array[string]",
    "description": "Planning periods indexed by $$t \\in \\mathcal{T}$$."
  },
  "resource_capacity": {
    "symbol": "$$b_r$$",
    "type": "array[number]",
    "shape": "$$|\\mathcal{R}|$$",
    "description": "Available capacity of each resource $$r \\in \\mathcal{R}$$."
  },
  "resource_requirement": {
    "symbol": "$$a_{p,r}$$",
    "type": "matrix[number]",
    "shape": "$$|\\mathcal{P}| \\times |\\mathcal{R}|$$",
    "description": "Amount of resource $$r$$ required to produce one unit of product $$p$$."
  },
  "tier_schedule": {
    "symbol": "$$\\{(\\ell_{p,k},u_{p,k},\\pi_{p,k})\\}_{k \\in \\mathcal{K}_p}$$",
    "type": "object",
    "description": "For each product $$p \\in \\mathcal{P}$$, an ordered list of sales-volume tiers. Each tier contains a lower bound $$\\ell_{p,k}$$, an upper bound $$u_{p,k}$$, and a unit profit $$\\pi_{p,k}$$. A missing upper bound means the tier is open-ended."
  }
}

Output Format
{
  "production_plan": {
    "type": "array[object]",
    "shape": "$$|\\mathcal{P}|$$",
    "description": "One record per product $$p \\in \\mathcal{P}$$.",
    "fields": {
      "product": {
        "type": "string",
        "description": "Product identifier $$p$$."
      },
      "quantity": {
        "symbol": "$$x_p$$",
        "type": "number",
        "description": "Chosen production and sales quantity for product $$p$$."
      },
      "selected_tier": {
        "symbol": "$$k_p$$",
        "type": "integer_or_label",
        "description": "Active sales-volume tier for product $$p$$."
      }
    }
  },
  "total_profit": {
    "symbol": "$$\\Pi$$",
    "type": "number",
    "description": "Total profit achieved by the chosen production plan."
  }
}

